template <int32 Capacity>
    requires (Capacity >= 0)
struct TFixedRowsStorage {
    using View = FFixedRowsView;
    using ConstView = FFixedRowsConstView;

    auto get_view(int32 const offset, int32 const count) -> View {
        return View{TArrayView<int32>{ids_.data() + offset, count},
                    children_.get_view(offset, count)};
    }
    auto get_const_view(int32 const offset, int32 const count) const -> ConstView {
        return ConstView{TConstArrayView<int32>{ids_.data() + offset, count},
                         children_.get_const_view(offset, count)};
    }

    template <typename TArg0, typename TArg1>
    void construct_at(int32 const index, TArg0&& new_ids, TArg1&& new_children_tracked) {
        ids_.construct_at(index, std::forward<TArg0>(new_ids));
        children_.construct_at(index, std::forward<TArg1>(new_children_tracked));
    }

    void default_construct_at(int32 const index) {
        ids_.construct_at(index);
        children_.default_construct_at(index);
    }

    void copy_construct_at(int32 const index,
                           TFixedRowsStorage const& other,
                           int32 const other_index) {
        ids_.construct_at(index, other.ids_[other_index]);
        children_.copy_construct_at(index, other.children_, other_index);
    }

    void move_construct_at(int32 const index, TFixedRowsStorage& other, int32 const other_index) {
        ids_.construct_at(index, MoveTemp(other.ids_[other_index]));
        children_.move_construct_at(index, other.children_, other_index);
    }

    template <typename SourceView>
    void construct_from_view_at(int32 const index,
                                SourceView const& source,
                                int32 const source_index) {
        ids_.construct_at(index, source.ids[source_index]);
        children_.construct_from_view_at(index, source.children, source_index);
    }

    template <typename SourceView>
    void copy_assign_from_view_at(int32 const dst_index,
                                  SourceView const& source,
                                  int32 const source_index) {
        ids_[dst_index] = source.ids[source_index];
        children_.copy_assign_from_view_at(dst_index, source.children, source_index);
    }

    void move_assign_at(int32 const dst_index, TFixedRowsStorage& other, int32 const source_index) {
        ids_[dst_index] = MoveTemp(other.ids_[source_index]);
        children_.move_assign_at(dst_index, other.children_, source_index);
    }

    void destroy_at(int32 const index) noexcept {
        children_.destroy_at(index);
        ids_.destroy_at(index);
    }

    ml::TFixedStorage<int32, Capacity> ids_;
    TFixedChildStorage<Capacity> children_;
};

template <int32 Capacity>
    requires (Capacity >= 0)
struct TFixedRows {
    using size_type = int32;
    using View = FFixedRowsView;
    using ConstView = FFixedRowsConstView;

    static constexpr size_type capacity_value{Capacity};

    inline static constexpr bool supports_copy_construction{std::is_copy_constructible_v<int32> &&
                                                            std::is_copy_constructible_v<FTracked>};
    inline static constexpr bool supports_move_construction{std::is_move_constructible_v<int32> &&
                                                            std::is_move_constructible_v<FTracked>};
    inline static constexpr bool supports_nothrow_move_construction{
        std::is_nothrow_move_constructible_v<int32> &&
        std::is_nothrow_move_constructible_v<FTracked>};
    inline static constexpr bool supports_default_construction{
        std::is_default_constructible_v<int32> && std::is_default_constructible_v<FTracked>};
    inline static constexpr bool supports_uninitialised_storage{
        std::is_trivially_copyable_v<int32> && std::is_trivially_destructible_v<int32> &&
        std::is_trivially_copyable_v<FTracked> && std::is_trivially_destructible_v<FTracked>};
    template <typename TArg0, typename TArg1>
    inline static constexpr bool supports_element_construction_from{
        std::is_constructible_v<int32, TArg0&&> && std::is_constructible_v<FTracked, TArg1&&>};

    TFixedRows() noexcept = default;
    TFixedRows(TFixedRows const& other)
        requires supports_copy_construction
    {
        for (size_type i{}; i < other.size_; ++i) {
            storage_.copy_construct_at(size_, other.storage_, i);
            ++size_;
        }
    }
    TFixedRows(TFixedRows const&)
        requires (!supports_copy_construction)
    = delete;
    TFixedRows(TFixedRows&& other) noexcept(supports_nothrow_move_construction)
        requires supports_move_construction
    {
        for (size_type i{}; i < other.size_; ++i) {
            storage_.move_construct_at(size_, other.storage_, i);
            ++size_;
        }
        other.reset();
    }
    TFixedRows(TFixedRows&&)
        requires (!supports_move_construction)
    = delete;
    ~TFixedRows() { reset(); }

    auto operator=(TFixedRows const& other) -> TFixedRows&
        requires supports_copy_construction
    {
        if (this != std::addressof(other)) {
            reset();
            append_from(other.get_const_view());
        }
        return *this;
    }
    auto operator=(TFixedRows const&) -> TFixedRows&
        requires (!supports_copy_construction)
    = delete;
    auto operator=(TFixedRows&& other) noexcept(supports_nothrow_move_construction) -> TFixedRows&
        requires supports_move_construction
    {
        if (this != std::addressof(other)) {
            reset();
            for (size_type i{}; i < other.size_; ++i) {
                storage_.move_construct_at(size_, other.storage_, i);
                ++size_;
            }
            other.reset();
        }
        return *this;
    }
    auto operator=(TFixedRows&&) -> TFixedRows&
        requires (!supports_move_construction)
    = delete;

    static constexpr auto capacity() noexcept -> size_type { return capacity_value; }
    auto num() const noexcept -> size_type { return size_; }
    auto is_empty() const noexcept -> bool { return size_ == 0; }
    auto is_full() const noexcept -> bool { return size_ == capacity(); }

    auto get_view() -> View { return storage_.get_view(0, size_); }
    auto get_view(size_type const offset, size_type const count) -> View {
        check_view_range(offset, count);
        return storage_.get_view(offset, count);
    }
    auto get_view() const -> ConstView { return get_const_view(); }
    auto get_view(size_type const offset, size_type const count) const -> ConstView {
        return get_const_view(offset, count);
    }
    auto get_const_view() const -> ConstView { return storage_.get_const_view(0, size_); }
    auto get_const_view(size_type const offset, size_type const count) const -> ConstView {
        check_view_range(offset, count);
        return storage_.get_const_view(offset, count);
    }
    auto slice(size_type const offset, size_type const count) -> View {
        return get_view(offset, count);
    }
    auto left(size_type const count) -> View { return slice(0, count); }
    auto right(size_type const count) -> View { return slice(size_ - count, count); }
    auto slice(size_type const offset, size_type const count) const -> ConstView {
        return get_const_view(offset, count);
    }
    auto left(size_type const count) const -> ConstView { return slice(0, count); }
    auto right(size_type const count) const -> ConstView { return slice(size_ - count, count); }

    template <typename TFunc>
    auto apply_arrays(TFunc&& func) -> decltype(auto) {
        auto view{get_view()};
        return view.apply_arrays(std::forward<TFunc>(func));
    }
    template <typename TFunc>
    auto apply_arrays(TFunc&& func) const -> decltype(auto) {
        auto view{get_const_view()};
        return view.apply_arrays(std::forward<TFunc>(func));
    }

    template <typename TArg0, typename TArg1>
        requires supports_element_construction_from<TArg0, TArg1>
    auto emplace_back(TArg0&& new_ids, TArg1&& new_children_tracked) -> size_type {
        check_has_sufficient_capacity(1);
        auto const index{size_};
        storage_.construct_at(
            index, std::forward<TArg0>(new_ids), std::forward<TArg1>(new_children_tracked));
        ++size_;
        return index;
    }
    template <typename TArg0, typename TArg1>
        requires supports_element_construction_from<TArg0, TArg1>
    auto add(TArg0&& new_ids, TArg1&& new_children_tracked) -> size_type {
        return emplace_back(std::forward<TArg0>(new_ids),
                            std::forward<TArg1>(new_children_tracked));
    }

    void add_defaulted(size_type const count = 1)
        requires supports_default_construction
    {
        check_has_sufficient_capacity(count);
        for (size_type i{}; i < count; ++i) {
            storage_.default_construct_at(size_);
            ++size_;
        }
    }
    void set_num(size_type const new_size)
        requires supports_default_construction
    {
        check(new_size >= 0);
        check(new_size <= capacity());
        if (new_size < size_) {
            destroy_from(new_size);
            return;
        }
        add_defaulted(new_size - size_);
    }
    void set_num(size_type const new_size, EAllowShrinking const)
        requires supports_default_construction
    {
        set_num(new_size);
    }
    auto capacity_view() -> View
        requires supports_uninitialised_storage
    {
        return storage_.get_view(0, capacity());
    }
    void set_num_uninitialised(size_type const new_size)
        requires supports_uninitialised_storage
    {
        check(new_size >= 0);
        check(new_size <= capacity());
        size_ = new_size;
    }
    void add_uninitialised(size_type const count)
        requires supports_uninitialised_storage
    {
        check_has_sufficient_capacity(count);
        size_ += count;
    }

    void pop() {
        check(!is_empty());
        --size_;
        storage_.destroy_at(size_);
    }
    void reset() noexcept { destroy_from(0); }
    void empty() noexcept { reset(); }
    void reserve(size_type const requested_capacity) const {
        check(requested_capacity >= 0);
        check(requested_capacity <= capacity());
    }
    void remove_at_swap(size_type const index, size_type const count, EAllowShrinking const) {
        check(index >= 0);
        check(count >= 0);
        check(index + count <= size_);
        if (count == 0) {
            return;
        }
        auto const available_tail{size_ - (index + count)};
        auto const move_count{count < available_tail ? count : available_tail};
        auto const source_begin{size_ - move_count};
        for (size_type i{}; i < move_count; ++i) {
            storage_.move_assign_at(index + i, storage_, source_begin + i);
        }
        destroy_from(size_ - count);
    }
    template <typename Other>
    void copy_element(size_type const dst_index, Other const& other, size_type const source_index) {
        check_index(dst_index);
        auto const source{other.get_const_view()};
        check(source_index >= 0);
        check(source_index < source.num());
        storage_.copy_assign_from_view_at(dst_index, source, source_index);
    }
    template <typename Other>
    void copy_elements(size_type const dst_index,
                       Other const& other,
                       size_type const source_index,
                       size_type const count) {
        check(dst_index >= 0);
        check(source_index >= 0);
        check(count >= 0);
        check(dst_index + count <= size_);
        auto const source{other.get_const_view()};
        check(source_index + count <= source.num());
        for (size_type i{}; i < count; ++i) {
            storage_.copy_assign_from_view_at(dst_index + i, source, source_index + i);
        }
    }
    template <typename Other>
    void append_from(Other const& other) {
        auto const source{other.get_const_view()};
        auto const count{source.num()};
        check_has_sufficient_capacity(count);
        for (size_type i{}; i < count; ++i) {
            storage_.construct_from_view_at(size_, source, i);
            ++size_;
        }
    }
  private:
    void check_index(size_type const index) const {
        check(index >= 0);
        check(index < size_);
    }
    void check_view_range(size_type const offset, size_type const count) const {
        check(offset >= 0);
        check(count >= 0);
        check(offset + count <= size_);
    }
    void check_has_sufficient_capacity(size_type const count) const {
        check(count >= 0);
        check(count <= capacity() - size_);
    }
    void destroy_from(size_type const first_index) noexcept {
        for (size_type i{size_}; i > first_index; --i) {
            storage_.destroy_at(i - 1);
        }
        size_ = first_index;
    }

    TFixedRowsStorage<Capacity> storage_;
    size_type size_{};
};

